def get_con_nbasis(con_type):
    """Return the number basis function for a given contraction type."""
    if con_type > 0:
        # Cartesian
        return (con_type+1)*(con_type+2)/2
    elif con_type == -1:
        raise ValueError
    else:
        # Pure
        return -2*con_type+1

