def __init__(self):
    self.data_dir = os.getenv('HORTONDATA')
    if self.data_dir is None:
        self.data_dir = './data'
    if not os.path.isdir(self.data_dir):
        raise IOError('Can not find the data files. The directory %s does not exist.' % self.data_dir)
